<?php require_once "../config/auth.php";requireAdmin();require_once "../config/database.php";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$cid=(int)$_POST["club_id"];$n=trim($_POST["event_name"]);$d=trim($_POST["description"]);$date=$_POST["event_date"];$time=$_POST["event_time"];$venue=trim($_POST["venue"]);$max=(int)$_POST["max_participants"];$deadline=$_POST["registration_deadline"]; $s=$conn->prepare("INSERT INTO events(club_id,event_name,description,event_date,event_time,venue,max_participants,registration_deadline) VALUES(?,?,?,?,?,?,?,?)");$s->bind_param("isssssis",$cid,$n,$d,$date,$time,$venue,$max,$deadline);$s->execute();$msg="Event added successfully!";}$clubs=$conn->query("SELECT club_id,club_name FROM clubs ORDER BY club_name");?><!DOCTYPE html><html><head><title>Add Event</title><link rel="stylesheet" href="../css/style.css"></head><body><nav class="navbar"><div class="logo">Admin</div><div class="nav-links"><a href="dashboard.php">Dashboard</a><a href="add-club.php">Add Club</a><a href="../logout.php">Logout</a></div></nav><div class="form-wrap"><div class="form-box"><h2>Add New Event</h2><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post"><label>Club</label><select name="club_id"><?php while($c=$clubs->fetch_assoc()):?><option value="<?=$c["club_id"]?>"><?=htmlspecialchars($c["club_name"])?></option><?php endwhile;?></select><label>Event Name</label><input name="event_name" required><label>Description</label><textarea name="description" required></textarea><label>Date</label><input type="date" name="event_date" required><label>Time</label><input type="time" name="event_time" required><label>Venue</label><input name="venue" required><label>Maximum Participants</label><input type="number" name="max_participants" min="1" value="100" required><label>Registration Deadline</label><input type="date" name="registration_deadline" required><button class="btn full">Add Event</button></form></div></div></body></html>